def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    weak_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                weak_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100 and opp.get('budget', 0) >= 300:
                    rich_aggressive += 1

    if not alive_opponents:
        return float(min(budget, 20.0))

    high_pressure = max(prev_bids) if prev_bids else 0.0
    avg_pressure = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply <= 16:
        urgency += 2
    elif supply <= 19:
        urgency += 1

    if day >= 8:
        urgency += 1

    if rich_aggressive >= 2 and urgency <= 2:
        base_bid = 8.0 if supply >= 20 else 12.0
    else:
        if urgency >= 6:
            base_bid = 125.0
        elif urgency >= 4:
            base_bid = 82.0
        elif urgency >= 2:
            base_bid = 42.0
        else:
            base_bid = 18.0

        if high_pressure > 0:
            if urgency >= 4:
                target = min(high_pressure + 3.0, 140.0)
                base_bid = max(base_bid, target)
            elif urgency <= 1 and high_pressure >= 100:
                base_bid = min(base_bid, 15.0)
            else:
                target = min(avg_pressure * 0.55 + 6.0, 65.0)
                base_bid = max(base_bid, target)

    if weak_opponents >= 2 and urgency <= 2:
        base_bid *= 0.8

    reserve = 0.0
    if day <= 3:
        reserve = 140.0
    elif day <= 7:
        reserve = 70.0

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 5:
        max_affordable = budget

    bid = min(base_bid, max_affordable)

    if urgency >= 5:
        bid = max(bid, min(budget, 90.0))
    elif urgency >= 3:
        bid = max(bid, min(budget, 45.0))

    if budget < 25:
        bid = budget

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    if my_status['hp'] < 4:
        bid = avg_prev_bid * 1.2
    else:
        bid = avg_prev_bid * 0.95
    return min(float(my_status['budget']), float(bid))
